m:0;display:flex;align-items:center;gap:12px;margin:22px -18px -20px;padding:13px 18px calc(13px + env(safe-area-inset-bottom));border-top:1px solid var(--line);background:#fff}.qty{display:flex;align-items:center;border:1.5px solid #d7dfda;border-radius:14px;overflow:hidden}.qty button{width:46px;height:50px;border:0;background:#fff;color:var(--green-dark);font-size:24px}.qty b{min-width:34px;text-align:center}.primary{height:52px;border:0;border-radius:14px;background:var(--green);color:#fff;font-weight:900}.add-submit{flex:1;padding:0 13px}
