<script>
const rupiah = number => 'Rp ' + Math.round(number).toLocaleString('id-ID');
const escapeHtml = value => String(value ?? '').replace(/[&<>'"]/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#039;','"':'&quot;'}[char]));
const byId=id=>document.getElementById(id);
const productDialog=byId('productDialog'),cartDialog=byId('cartDialog'),pdQty=byId('pdQty'),pdName=byId('pdName'),pdDesc=byId('pdDesc'),pdImage=byId('pdImage'),pdNote=byId('pdNote'),pdPrice=byId('pdPrice'),variantBox=byId('variantBox'),addonBox=byId('addonBox'),qtyMinus=byId('qtyMinus'),qtyPlus=byId('qtyPlus'),addProduct=byId('addProduct'),cartButton=byId('cartButton'),cartBadge=byId('cartBadge'),cartTotal=byId('cartTotal'),checkoutTotal=byId('checkoutTotal'),checkoutArea=byId('checkoutArea'),cartLines=byId('cartLines'),menuSearch=byId('menuSearch'),emptySearch=byId('emptySearch'),checkoutButton=byId('checkoutButton'),checkoutError=byId('checkoutError'),guestName=byId('guestName');let selected=null,selectedQty=1,cart=[];
document.querySelectorAll('[data-close]').forEach(button=>button.addEventListener('click',()=>document.getElementById(button.dataset.close).close()));
document.querySelectorAll('dialog').forEach(dialog=>dialog.addEventListener('click',event=>{if(event.target===dialog)dialog.close()}));
document.querySelectorAll('.product-card').forEach(button=>button.addEventListener('click',()=>openProduct(JSON.parse(button.dataset.product))));
function openProduct(product){selected=product;selectedQty=1;pdQty.textContent=selectedQty;pdName.textContent=product.name;pdDesc.textContent=product.description||rupiah(product.price);pdImage.innerHTML=`<span>${escapeHtml(product.initial)}</span>`;if(product.image){const img=new Image();img.alt='';img.src=product.image;img.onerror=()=>img.remove();pdImage.appendChild(img)}pdNote.value='';variantBox.innerHTML=product.variants.length?`<div class="option-group"><p>Pilih variasi</p>${product.variants.map((variant,index)=>`<label class="option"><input type="radio" name="variant" value="${variant.id}" data-adj="${variant.adjustment}" ${index===0?'checked':''}><span>${escapeHtml(variant.name)}</span><em>${variant.adjustment?'+ '+rupiah(variant.adjustment):'Termasuk'}</em></label>`).join('')}</div>`:'';addonBox.innerHTML=product.addons.length?`<div class="option-group"><p>Tambahan</p>${product.addons.map(addon=>`<label class="option"><input type="checkbox" name="addon" value="${addon.id}" data-price="${addon.price}"><span>${escapeHtml(addon.name)}</span><em>+ ${rupiah(addon.price)}</em></label>`).join('')}</div>`:'';updateProductTotal();productDialog.showModal()}
function productUnitTotal(){const variant=productDialog.querySelector('[name=variant]:checked'),addons=[...productDialog.querySelectorAll('[name=addon]:checked')];return selected.price+(variant?Number(variant.dataset.adj):0)+addons.reduce((sum,addon)=>sum+Number(addon.dataset.price),0)}
function updateProductTotal(){pdPrice.textContent=rupiah(productUnitTotal()*selectedQty)}productDialog.addEventListener('change',updateProductTotal);
qtyMinus.addEventListener('click',()=>{selectedQty=Math.max(1,selectedQty-1);pdQty.textContent=selectedQty;updateProductTotal()});qtyPlus.addEventListener('click',()=>{selectedQty=Math.min(99,selectedQty+1);pdQty.textContent=selectedQty;updateProductTotal()});
addProduct.addEventListener('click',()=>{const variant=productDialog.querySelector('[name=variant]:checked'),addons=[...productDialog.querySelectorAll('[name=addon]:checked')];cart.push({product_id:selected.id,name:selected.name,price:selected.price,qty:selectedQty,variant_id:variant?Number(variant.value):null,variant_name:variant?variant.closest('label').querySelector('span').textContent:'',variant_adjustment:variant?Number(variant.dataset.adj):0,addons:addons.map(addon=>({addon_id:Number(addon.value),name:addon.closest('label').querySelector('span').textContent,price:Number(addon.dataset.price)})),notes:pdNote.value.trim()});productDialog.close();renderCart()});
const lineTotal=item=>(item.price+item.variant_adjustment+item.addons.reduce((sum,addon)=>sum+addon.price,0))*item.qty,cartTotalValue=()=>cart.reduce((sum,item)=>sum+lineTotal(item),0);
function changeQty(index,delta){cart[index].qty+=delta;if(cart[index].qty<1)cart.splice(index,1);renderCart()}function removeLine(index){cart.splice(index,1);renderCart()}
function renderCart(){const count=cart.reduce((sum,item)=>sum+item.qty,0);cartButton.hidden=!count;cartButton.style.display=count?'flex':'none';cartBadge.textContent=count;cartTotal.textContent=rupiah(cartTotalValue());checkoutTotal.textContent=rupiah(cartTotalValue());checkoutArea.hidden=!cart.length;cartLines.innerHTML=cart.length?cart.map((item,index)=>{const details=[item.variant_name,item.addons.map(addon=>addon.name).join(', '),item.notes?`Catatan: ${item.notes}`:''].filter(Boolean).join(' · ');return `<div class="cart-line"><div class="line-top"><strong>${escapeHtml(item.name)}</strong><b>${rupiah(lineTotal(item))}</b></div>${details?`<p class="line-detail">${escapeHtml(details)}</p>`:''}<div class="line-actions"><div class="mini-qty"><button type="button" onclick="changeQty(${index},-1)" aria-label="Kurangi">−</button><span>${item.qty}</span><button type="button" onclick="changeQty(${index},1)" aria-label="Tambah">+</button></div><button type="button" class="remove" onclick="removeLine(${index})">Hapus</button></div></div>`}).join(''):'<div class="cart-empty"><b>Belum ada menu dipilih</b><p>Tutup halaman ini lalu ketuk tombol + pada menu.</p></div>'}
cartButton.addEventListener('click',()=>{renderCart();cartDialog.showModal()});
menuSearch.addEventListener('input',()=>{const query=menuSearch.value.trim().toLocaleLowerCase('id');let visible=0;document.querySelectorAll('.product-card').forEach(card=>{const show=card.dataset.name.includes(query);card.hidden=!show;if(show)visible++});document.querySelectorAll('.menu-section').forEach(section=>section.hidden=![...section.querySelectorAll('.product-card')].some(card=>!card.hidden));emptySearch.style.display=visible?'none':'block'});
document.querySelectorAll('.category-chip').forEach(chip=>chip.addEventListener('click',()=>{document.querySelectorAll('.category-chip').forEach(item=>item.classList.remove('active'));chip.classList.add('active');menuSearch.value='';menuSearch.dispatchEvent(new Event('input'));if(chip.dataset.target!=='all')document.getElementById(chip.dataset.target)?.scrollIntoView({behavior:'smooth',block:'start'});else window.scrollTo({top:0,behavior:'smooth'})}));
checkoutButton.addEventListener('click',async()=>{checkoutButton.disabled=true;checkoutButton.textContent='Mengirim pesanan…';checkoutError.hidden=true;try{const response=await fetch(@json(route('self-order.place',$table->public_token)),{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]').content},body:JSON.stringify({session_token:@json($session->guest_token),guest_name:guestName.value,payment_choice:document.querySelector('[name=payment]:checked').value,items:cart.map(item=>({product_id:item.product_id,qty:item.qty,variant_id:item.variant_id,addons:item.addons.map(addon=>({addon_id:addon.addon_id})),notes:item.notes}))})});const data=await response.json();if(!response.ok)throw new Error(data.message||'Pesanan belum berhasil dikirim.');location.href=data.status_url}catch(exception){checkoutError.textContent=exception.message;checkoutError.hidden=false;checkoutButton.disabled=false;checkoutButton.textContent='Kirim pesanan'}});
</script>
</body>
</html>
